function lp21_name_variants($value): array {
    $raw=trim((string)$value); if($raw==='') return [];
    $out=[$raw];
    if(preg_match_all('/\(\s*(?:ex|ех)\s*\.?\s*([^)]{2,160})\)/iu',$raw,$m)) foreach($m[1] as $x) if(trim((string)$x)!=='') $out[]=trim((string)$x);
    $base=preg_replace('/\s*\(\s*(?:ex|ех)\s*\.?\s*[^)]{2,160}\)\s*/iu',' ',$raw);
    if(is_string($base)&&trim($base)!=='') $out[]=trim($base);
    return array_values(array_unique($out));
}
function lp21_tokens($value): array {
    $drop=['hotel'=>1,'hotels'=>1,'отель'=>1,'отели'=>1,'resort'=>1,'resorts'=>1,'резорт'=>1,'ресорт'=>1,'spa'=>1,'спа'=>1];
    $parts=[]; foreach(explode(' ',fc_norm($value)) as $x) if($x!==''&&!isset($drop[$x])) $parts[]=$x;
    return $parts;
}
function lp21_key($value): string { return implode(' ',lp21_tokens($value)); }
function lp21_keys(array $names): array {
    $out=[]; foreach($names as $n) foreach(lp21_name_variants((string)$n) as $v){$k=lp21_key($v);if($k!=='')$out[$k]=true;} return array_keys($out);
}
